//#region ../rules/src/pay-bands.ts
	function currentPayStepOrdinal(schedule, serviceMonthOrdinal) {
		if (schedule.status !== "READY" || !schedule.current || serviceMonthOrdinal === null) return null;
		const ordinal = serviceMonthOrdinal - schedule.current.fromServiceMonthOrdinal + 1;
		return ordinal >= 1 ? ordinal : null;
	}
	/**
	* When each base-pay band (이병·일병·상병·병장 상당) begins for this profile.
	*
	* Boundaries follow 병역법 시행령 제62조①: the calendar month containing the
	* call-up date is service month 1, plus an institution-confirmed 제62조②
	* credit in whole months. Band boundaries come from the bundle in force on
	* `asOfDate`; each amount is taken only from a bundle verified for the date
	* the band starts. This is a schedule of *when*, not a payroll calculation:
	* proration, non-payable days and allowances stay in
	* `evaluateMonthlyCompensation`.
	*/
	function derivePayBandSchedule(profile, asOfDate, bundles = COMPENSATION_RULE_BUNDLES) {
		let credit;
		if (profile.priorServiceCredit === null) return {
			status: "NEEDS_INPUT",
			reason: "이전 복무 경력 여부를 알려 주시면 급여 단계를 보여 드려요."
		};
		else if (profile.priorServiceCredit === "NONE") credit = 0;
		else if (profile.priorServiceCreditHasPartialMonth || profile.priorServiceCreditedMonths === null) return {
			status: "NEEDS_INPUT",
			reason: "복무기관이 확인한 인정 개월 수가 있어야 급여 단계를 정할 수 있어요."
		};
		else credit = profile.priorServiceCreditedMonths;
		const selection = selectRuleByDate("COMPENSATION", bundles, asOfDate);
		if (selection.status !== "SUPPORTED") return {
			status: "UNSUPPORTED",
			reason: "오늘 적용되는 검증된 보수 규칙이 없어요."
		};
		const bands = selection.rule.basePay.serviceMonthBands;
		const callUpMonthStart = `${profile.callUpDate.slice(0, 7)}-01`;
		const steps = [];
		for (const band of bands) {
			const monthOffset = band.fromServiceMonthOrdinal - 1 - credit;
			const startDate = monthOffset <= 0 ? profile.callUpDate : addCalendarMonths(callUpMonthStart, monthOffset);
			if (compareDateOnly(startDate, profile.expectedDischargeDate) > 0) break;
			const endOrdinal = band.toServiceMonthOrdinal;
			if (endOrdinal !== null && endOrdinal - credit < 1) continue;
			const amountSelection = selectRuleByDate("COMPENSATION", bundles, startDate);
			let monthlyAmount = null;
			let amountRuleVersion = null;
			if (amountSelection.status === "SUPPORTED") {
				const ordinal = calculateServiceMonthIndex(profile.callUpDate, startDate) + 1 + credit;
				const amountBand = amountSelection.rule.basePay.serviceMonthBands.find((candidate) => ordinal >= candidate.fromServiceMonthOrdinal && (candidate.toServiceMonthOrdinal === null || ordinal <= candidate.toServiceMonthOrdinal));
				if (amountBand?.equivalentRank === band.equivalentRank) {
					monthlyAmount = amountBand.monthlyAmount;
					amountRuleVersion = amountSelection.rule.version;
				}
			}
			steps.push({
				equivalentRank: band.equivalentRank,
				label: EQUIVALENT_RANK_LABELS[band.equivalentRank] ?? band.equivalentRank,
				fromServiceMonthOrdinal: band.fromServiceMonthOrdinal,
				startDate,
				monthlyAmount,
				amountRuleVersion
			});
		}
		const current = [...steps].reverse().find((step) => compareDateOnly(step.startDate, asOfDate) <= 0) ?? null;
		const next = steps.find((step) => compareDateOnly(step.startDate, asOfDate) > 0) ?? null;
		return {
			status: "READY",
			ruleVersion: selection.rule.version,
			creditedMonths: credit,
			current,
			next,
			steps
		};
	}

