	function normalizeLabel(value) {
		return value.normalize("NFKC").trim().toLowerCase().replace(/[\s_\-./()[\]{}:]+/g, "");
	}
	function classifyEventType(value) {
		const source = typeof value === "string" ? normalizeLabel(value) : "";
		if (!source) return {
			eventType: null,
			confidence: 0,
			warnings: [{
				code: "MISSING_EVENT_TYPE",
				message: "복무/휴가 종류가 비어 있습니다."
			}],
			halfDayHint: false,
			halfDayPart: null
		};
		const halfDayPart = source.includes("오전") ? "AM" : source.includes("오후") ? "PM" : null;
		const labels = EVENT_TYPE_SYNONYMS.flatMap((candidate) => candidate.labels.map((label) => ({
			type: candidate.type,
			normalized: normalizeLabel(label)
		})));
		const exact = labels.find((label) => source === label.normalized);
		if (exact) return {
			eventType: exact.type,
			confidence: 1,
			warnings: [],
			halfDayHint: source.includes("반가"),
			halfDayPart
		};
		const partial = labels.filter((label) => label.normalized.length >= 2 && (source.includes(label.normalized) || label.normalized.includes(source))).sort((a, b) => b.normalized.length - a.normalized.length || a.type.localeCompare(b.type))[0];
		if (partial) return {
			eventType: partial.type,
			confidence: .86,
			warnings: [],
			halfDayHint: source.includes("반가"),
			halfDayPart
		};
		return {
			eventType: null,
			confidence: .35,
			warnings: [{
				code: "UNRECOGNIZED_EVENT_TYPE",
				message: `복무/휴가 종류 '${String(value)}'를 자동 분류하지 못했습니다.`
			}],
			halfDayHint: false,
			halfDayPart: null
		};
	}

