	function applyFormPatch(current, patch) {
		const next = {
			...current,
			...patch
		};
		if (next.mode === "HALF_DAY" && next.eventType !== "ANNUAL_LEAVE") next.mode = "PARTIAL";
		if (isCompensationNonPayableEventType(next.eventType) && next.mode !== "ALL_DAY") next.mode = "ALL_DAY";
		if (next.mode === "ALL_DAY" && !next.dayCountTouched && isDateOnly(next.startDate) && isDateOnly(next.endDate) && next.startDate <= next.endDate) next.dayCount = String(isCompensationNonPayableEventType(next.eventType) ? inclusiveDaySpan(next.startDate, next.endDate) : Math.max(1, countWeekdays(next.startDate, next.endDate)));
		if (next.mode === "PARTIAL" && !next.durationTouched && /^\d{2}:\d{2}$/.test(next.startTime) && /^\d{2}:\d{2}$/.test(next.endTime)) {
			const between = clockToMinutes(next.endTime) - clockToMinutes(next.startTime);
			if (between > 0) {
				next.hours = String(Math.floor(between / 60));
				next.minutes = String(between % 60);
			}
		}
		return next;
	}

