	const PURE_FUNCTION_NAMES = Object.keys(PURE);
	function revive(value) {
		if (Array.isArray(value)) return value.map(revive);
		if (value !== null && typeof value === "object") {
			const record = value;
			const keys = Object.keys(record);
			if (keys.length === 1 && keys[0] === "$instant") {
				const instant = new Date(String(record.$instant));
				if (Number.isNaN(instant.getTime())) throw new RangeError(`Invalid instant: ${String(record.$instant)}`);
				return instant;
			}
			return Object.fromEntries(keys.map((key) => [key, revive(record[key])]));
		}
		return value;
	}
	/**
	* Run one store command as a pure function with a deterministic context
	* (fixed clock, device id and id sequence), so command behaviour itself can
	* be fixtured and replayed on another engine.
	*/
	function applyCommand(commands, name, data, args, context) {
		const command = commands[name];
		if (!command) return {
			ok: false,
			error: {
				name: "UnknownCommand",
				message: `Unknown command: ${name}`
			}
		};
		const ids = [...context.ids];
		const commandContext = {
			now: context.now,
			deviceId: context.deviceId,
			createId: () => {
				const id = ids.shift();
				if (!id) throw new Error("Fixture context ran out of ids.");
				return id;
			}
		};
		try {
			return {
				ok: true,
				value: command(...[
					revive(data),
					...args.map(revive),
					commandContext
				])
			};
		} catch (error) {
			const failure = error instanceof Error ? error : new Error(String(error));
			return {
				ok: false,
				error: {
					name: failure.name,
					message: failure.message
				}
			};
		}
	}
	/**
	* Calls never throw across the bridge: a thrown `RangeError` from the domain
	* (an invalid date, for example) is part of the observable contract and is
	* fixtured as `{ ok: false, error }`.
	*/
	function callPure(name, args) {
		const fn = PURE[name];
		if (!fn) return {
			ok: false,
			error: {
				name: "UnknownFunction",
				message: `Unknown function: ${name}`
			}
		};
		try {
			const value = fn(...args.map(revive));
			return {
				ok: true,
				value: value === void 0 ? null : value
			};
		} catch (error) {
			const failure = error instanceof Error ? error : new Error(String(error));
			return {
				ok: false,
				error: {
					name: failure.name,
					message: failure.message
				}
			};
		}
	}

